import { CHECK_ICON_PATH, GIFT_ICON_PATH, STAMP_ICON_PATHS } from './stamp-icons'

/**
 * The stamp glyphs as the native apps store them: one Android VectorDrawable and one
 * iOS template SVG each, drawn as the same 2px round strokes on the 24 grid.
 *
 * Generated by `scripts/native-stamp-icons.ts`; a test compares the files in the apps
 * with this output so a glyph changed here cannot silently drift there.
 */
export interface NativeStampGlyph {
  /** `coffee`, `ice-cream`, `gift`… the asset name on iOS. */
  name: string
  /** `stamp_coffee`, `stamp_ice_cream`… resource names only allow `[a-z0-9_]`. */
  androidName: string
  path: string
  androidXml: string
  svg: string
}

export function nativeStampGlyphs(): NativeStampGlyph[] {
  const entries: Array<[string, string]> = [
    ...Object.entries(STAMP_ICON_PATHS),
    ['gift', GIFT_ICON_PATH],
    ['check', CHECK_ICON_PATH],
  ]
  return entries.map(([name, path]) => ({
    name,
    androidName: `stamp_${name.replace(/-/g, '_')}`,
    path,
    androidXml: [
      '<?xml version="1.0" encoding="utf-8"?>',
      '<!-- Generated from packages/shared/src/stamp-icons.ts. Do not edit by hand. -->',
      '<vector xmlns:android="http://schemas.android.com/apk/res/android"',
      '    android:width="24dp"',
      '    android:height="24dp"',
      '    android:viewportWidth="24"',
      '    android:viewportHeight="24">',
      '    <path',
      '        android:fillColor="#00000000"',
      '        android:strokeColor="#FFFFFFFF"',
      '        android:strokeWidth="2"',
      '        android:strokeLineCap="round"',
      '        android:strokeLineJoin="round"',
      `        android:pathData="${path}" />`,
      '</vector>',
      '',
    ].join('\n'),
    svg: `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"><path d="${path}" fill="none" stroke="#000000" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>\n`,
  }))
}
